/* Lot 109: heights, min-heights and max-heights past 2000 px (parse_height, up to WE_LAYOUT_MAX) in style attributes and sheets, stacked (generated by scripts/lot109_gen.py; expectations from scripts/lot109_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include "webeng.h"

static we_doc_t g_doc;
static we_node_t g_none;

static void lay(const char *html) {
    TEST_ASSERT_EQUAL(0, we_parse(&g_doc, html, (int)strlen(html)));
    TEST_ASSERT_EQUAL(0, we_style(&g_doc));
    TEST_ASSERT_EQUAL(0, we_layout_viewport(&g_doc, 640, 480));
}

static const we_node_t *nd(const char *id) {
    int i;
    for (i = 0; i < (int)g_doc.nnodes; i++)
        if (!strcmp(g_doc.nodes[i].id, id)) return &g_doc.nodes[i];
    g_none.h = g_none.y = -1;
    return &g_none;     /* -1: no such node */
}

static void test_l109_tall_0(void) {
    lay("<body style='margin:0'><div id=d0 style='max-height:2001.5px;height:1645px'></div></body>");
    TEST_ASSERT_EQUAL(1645, nd("d0")->h);
    TEST_ASSERT_EQUAL(0, nd("d0")->y);
    lay("<html><head><style>body { margin: 0 } #d1 { height: 2500% } #d2 { min-height: 999px; max-height: 1158px; height: 16001px }</style></head><body><div id=d0></div><div id=d1></div><div id=d2></div></body></html>");
    TEST_ASSERT_EQUAL(0, nd("d0")->h);
    TEST_ASSERT_EQUAL(0, nd("d0")->y);
    TEST_ASSERT_EQUAL(0, nd("d1")->h);
    TEST_ASSERT_EQUAL(0, nd("d1")->y);
    TEST_ASSERT_EQUAL(999, nd("d2")->h);
    TEST_ASSERT_EQUAL(0, nd("d2")->y);
    lay("<body style='margin:0'><div id=d0 style='min-height:14864px'></div><div id=d1 style='height:1999px;max-height:247px'></div><div id=d2 style='height:10290px;height:1208px;height:9390px'></div></body>");
    TEST_ASSERT_EQUAL(14864, nd("d0")->h);
    TEST_ASSERT_EQUAL(0, nd("d0")->y);
    TEST_ASSERT_EQUAL(247, nd("d1")->h);
    TEST_ASSERT_EQUAL(14864, nd("d1")->y);
    TEST_ASSERT_EQUAL(9390, nd("d2")->h);
    TEST_ASSERT_EQUAL(15111, nd("d2")->y);
    lay("<body style='margin:0'><div id=d0 style='height:7749px;height:2500%;min-height:1704px'></div></body>");
    TEST_ASSERT_EQUAL(7749, nd("d0")->h);
    TEST_ASSERT_EQUAL(0, nd("d0")->y);
    lay("<html><head><style>body { margin: 0 } #d0 { height: 2356px; max-height: 16001px }</style></head><body><div id=d0></div></body></html>");
    TEST_ASSERT_EQUAL(2356, nd("d0")->h);
    TEST_ASSERT_EQUAL(0, nd("d0")->y);
    lay("<html><head><style>body { margin: 0 } #d0 { min-height: 225px; min-height: 4316px; height: 193px } #d1 { min-height: 16001px; height: 1999px; height: 10654px }</style></head><body><div id=d0></div><div id=d1></div></body></html>");
    TEST_ASSERT_EQUAL(4316, nd("d0")->h);
    TEST_ASSERT_EQUAL(0, nd("d0")->y);
    TEST_ASSERT_EQUAL(10654, nd("d1")->h);
    TEST_ASSERT_EQUAL(4316, nd("d1")->y);
    lay("<body style='margin:0'><div id=d0 style='max-height:15999px;height:1769px'></div><div id=d1></div><div id=d2 style='max-height:1999px;max-height:176px'></div><div id=d3></div></body>");
    TEST_ASSERT_EQUAL(1769, nd("d0")->h);
    TEST_ASSERT_EQUAL(0, nd("d0")->y);
    TEST_ASSERT_EQUAL(0, nd("d1")->h);
    TEST_ASSERT_EQUAL(1769, nd("d1")->y);
    TEST_ASSERT_EQUAL(0, nd("d2")->h);
    TEST_ASSERT_EQUAL(1769, nd("d2")->y);
    TEST_ASSERT_EQUAL(0, nd("d3")->h);
    TEST_ASSERT_EQUAL(1769, nd("d3")->y);
    lay("<html><head><style>body { margin: 0 } #d0 { max-height: 1093px; max-height: 11913px; height: 3499px } #d1 { min-height: 14411px } #d2 { height: 107px; height: 50%; height: 7535px }</style></head><body><div id=d0></div><div id=d1></div><div id=d2></div></body></html>");
    TEST_ASSERT_EQUAL(3499, nd("d0")->h);
    TEST_ASSERT_EQUAL(0, nd("d0")->y);
    TEST_ASSERT_EQUAL(14411, nd("d1")->h);
    TEST_ASSERT_EQUAL(3499, nd("d1")->y);
    TEST_ASSERT_EQUAL(7535, nd("d2")->h);
    TEST_ASSERT_EQUAL(16000, nd("d2")->y);
    lay("<body style='margin:0'><div id=d0></div></body>");
    TEST_ASSERT_EQUAL(0, nd("d0")->h);
    TEST_ASSERT_EQUAL(0, nd("d0")->y);
    lay("<html><head><style>body { margin: 0 } #d0 { min-height: 1999px } #d1 { min-height: 209px; height: 2000%; min-height: 731px } #d2 { height: 16001px; height: 15999px }</style></head><body><div id=d0></div><div id=d1></div><div id=d2></div><div id=d3></div></body></html>");
    TEST_ASSERT_EQUAL(1999, nd("d0")->h);
    TEST_ASSERT_EQUAL(0, nd("d0")->y);
    TEST_ASSERT_EQUAL(731, nd("d1")->h);
    TEST_ASSERT_EQUAL(1999, nd("d1")->y);
    TEST_ASSERT_EQUAL(15999, nd("d2")->h);
    TEST_ASSERT_EQUAL(2730, nd("d2")->y);
    TEST_ASSERT_EQUAL(0, nd("d3")->h);
    TEST_ASSERT_EQUAL(16000, nd("d3")->y);
}

